#include "dmx_graph.cpp"
#include "studio_obj_session_snapshot_candidate.h"
#include <cstdlib>
static void check(bool b){if(!b)std::abort();}
int main(){auto graph=loadGraph("work/short-timeline-session.dmx");auto original=graph;std::istringstream source("v 0 0 0\nv 1 0 0\nv 0 1 0\nusemtl A\nf 1 2 3\n");VtfRgbaImageCandidate image;image.width=image.height=2048;image.rgba.assign(2048u*2048u*4u,255);auto owner=std::make_shared<RetainedObjSceneCandidate>(studioReadObjCandidate(source),std::map<std::string,VtfRgbaImageCandidate>{{"A",image}},.5f);studioEmbedObjSessionCandidate(graph,owner);auto path="outputs/obj-session-large-"+std::to_string(GetCurrentProcessId())+".dmx";saveGraph(graph,path.c_str());auto reloaded=loadGraph(path.c_str());auto restored=studioReadObjSessionCandidate(reloaded);check(restored&&restored->scale()==.5f&&restored->textureInputs().materials[0].image.rgba==image.rgba);auto root=sessionRenderRootCandidate(reloaded);auto findSnapshot=[&](Graph&g)->Attribute&{for(auto&a:g.elements[root].attributes)if(g.strings[a.name]==objSessionSnapshotNameCandidate)return a;throw std::runtime_error("missing fixture attribute");};
 size_t rejected=0;for(unsigned mode=0;mode<4;++mode){auto bad=reloaded;auto&a=findSnapshot(bad);if(mode==0)bad.elements[root].attributes.push_back(a);else if(mode==1)a.type=20;else if(mode==2)a.values.push_back(a.values[0]);else a.values[0].wire.pop_back();try{studioReadObjSessionCandidate(bad);std::abort();}catch(const std::exception&){++rejected;}}
 auto stringsBefore=reloaded.strings;auto wireBefore=findSnapshot(reloaded).values[0].wire;auto invalidModel=owner->sourceModel();invalidModel.materialLibraries.push_back(std::string(1048577,'x'));auto invalidOwner=std::make_shared<RetainedObjSceneCandidate>(invalidModel);try{studioEmbedObjSessionCandidate(reloaded,invalidOwner);std::abort();}catch(const std::exception&){}check(reloaded.strings==stringsBefore&&findSnapshot(reloaded).values[0].wire==wireBefore);check(studioReadObjSessionCandidate(reloaded)->scale()==.5f);
 studioEmbedObjSessionCandidate(reloaded,{});check(!studioReadObjSessionCandidate(reloaded));check(original.elements.size()==graph.elements.size());std::filesystem::remove(path);std::cout<<"obj_session_large_embedded_image=passed bytes="<<image.rgba.size()<<" null_owner_removes_attribute=1 malformed_attributes_rejected="<<rejected<<" failed_embed_preserves_previous=1\n";}
